// Validate the upload, redact secrets, and cap log size so one run stays under Groq's free 8K tokens/min.
const MODEL_LOG_LIMIT = 6000;   // chars sent to the model (~1.5k tokens)
const JIRA_LOG_LIMIT = 30000;   // chars kept in the Jira description

const item = $input.first();
const form = item.json;
const files = item.binary || {};
const fileKey = Object.keys(files)[0];
if (!fileKey) throw new Error('No screenshot was uploaded.');
const shot = files[fileKey];
if (!/^image\/(png|jpe?g|webp)$/i.test(shot.mimeType || '')) {
  throw new Error('Unsupported file type "' + shot.mimeType + '". Upload a PNG, JPG or WEBP screenshot.');
}

const redact = (s) => String(s || '')
  .replace(/\bBearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]')
  .replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, '[REDACTED_JWT]')
  .replace(/\b(?:sk|gsk|pk|rk|ghp|gho|xox[abp])[-_][A-Za-z0-9_-]{10,}/g, '[REDACTED_KEY]')
  .replace(/((?:password|passwd|pwd|secret|token|api[_-]?key|access[_-]?key|client[_-]?secret)["']?\s*[:=]\s*["']?)[^\s"',;&]+/gi, '$1[REDACTED]');

// Keep the head and the tail (where the stack trace usually ends).
const clip = (s, n) => s.length <= n ? s
  : s.slice(0, Math.floor(n * 0.4)) + '\n... [' + (s.length - n) + ' chars truncated] ...\n' + s.slice(-Math.ceil(n * 0.6));

// LangChain prompt templates treat curly braces as variables, so swap them in model-bound text only.
const safeForPrompt = (s) => s.replace(/\{/g, '(').replace(/\}/g, ')');

const logs = redact(form['Error Logs']).trim();
const notes = redact(form['What were you doing?']).trim();
const environment = redact(form['Environment']).trim();

return [{
  json: {
    userNotes: notes,
    environment,
    promptNotes: safeForPrompt(notes),
    promptEnvironment: safeForPrompt(environment),
    promptLogs: safeForPrompt(clip(logs, MODEL_LOG_LIMIT)),
    logsForJira: clip(logs, JIRA_LOG_LIMIT),
    hasLogs: logs.length > 0,
    logsTruncated: logs.length > MODEL_LOG_LIMIT,
    screenshotName: shot.fileName || 'screenshot.png',
    submittedAt: form.submittedAt || new Date().toISOString(),
  },
  binary: { screenshot: shot },
}];

