parameters.jsCode:
// Turn the model's JSON into Jira wiki markup (the Jira node posts to REST API v2).
const report = $input.first().json.output;
const input = $('Prepare Input').first();
const ctx = input.json;

const text = (s) => String(s ?? '').trim() || '_Not provided_';
const bullets = (arr, mark = '*') => (Array.isArray(arr) && arr.length)
  ? arr.map((x) => mark + ' ' + String(x).trim()).join('\n') : '_None_';
const cell = (s) => String(s ?? '').replace(/\|/g, '/').replace(/\s*\n\s*/g, ' ').trim() || ' ';
const steps = (report.steps_to_reproduce || []).map((s) => String(s).replace(/^\s*\d+[.)]\s*/, ''));

const visuals = (report.visual_observations || []).length
  ? '||Element||Location||Observation||\n' + report.visual_observations
      .map((v) => '|' + cell(v.element) + '|' + cell(v.location) + '|' + cell(v.observation) + '|').join('\n')
  : '_None_';

const logs = ctx.hasLogs
  ? '{noformat}\n' + ctx.logsForJira.replace(/\{noformat\}/gi, '(noformat)') + '\n{noformat}'
  : '_No logs provided._';

const description = [
  'h3. Summary', text(report.summary), '',
  '*Severity:* ' + report.severity + ' | *Confidence:* ' + report.confidence + ' | *Affected area:* ' + text(report.affected_area),
  '*Environment:* ' + text(ctx.environment || report.environment), '',
  'h3. Preconditions', bullets(report.preconditions), '',
  'h3. Steps to Reproduce', bullets(steps, '#'), '',
  'h3. Expected Result', text(report.expected_result), '',
  'h3. Actual Result', text(report.actual_result), '',
  'h3. Visual Observations', visuals, '',
  'h3. Error Messages Detected', bullets(report.error_messages_detected), '',
  'h3. Log Analysis', text(report.log_analysis), '',
  'h3. Suspected Cause', text(report.suspected_cause), '',
  'h3. Missing Information', bullets(report.missing_info), '',
  'h3. Tester Notes', ctx.userNotes ? '{quote}' + ctx.userNotes + '{quote}' : '_Not provided_', '',
  'h3. Error Logs', logs, '',
  '----',
  '_Drafted by the Screenshot-to-Bug-Reporter n8n agent from "' + ctx.screenshotName + '" on ' + ctx.submittedAt + '. Please review before triage._',
].join('\n');

const slug = (s) => String(s).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const labels = [...new Set([
  'ai-bug-report', 'from-screenshot', 'severity-' + slug(report.severity),
  ...(report.labels || []).map(slug),
])].filter(Boolean).slice(0, 8);

return [{
  json: {
    summary: String(report.title || 'Bug from screenshot').replace(/\s+/g, ' ').trim().slice(0, 250),
    description,
    labels,
    severity: report.severity,
    confidence: report.confidence,
  },
  binary: input.binary,
}];

// The Jira create response has no binary data, so re-attach the screenshot for the upload step.
const created = $input.first().json;
const formatted = $('Format Jira Description').first();
return [{
  json: {
    key: created.key,
    url: 'https://nancyverma0591.atlassian.net/browse/' + created.key,
    title: formatted.json.summary,
    severity: formatted.json.severity,
    confidence: formatted.json.confidence,
  },
  binary: formatted.binary,
}];

